begin;
create extension if not exists pgtap with schema extensions;
select plan(23);
select has_table('public','material_intake_lots','physical intake lot table exists');
select has_column('public','material_receipts','material_source_id','receipt has canonical source FK');
select has_column('public','material_receipts','accepted_weight_kg','receipt stores accepted mass');
select has_column('public','material_receipts','improper_weight_kg','receipt stores improper mass');
select has_column('public','material_receipts','vehicle_plate','receipt stores transport plate');
select ok((select relrowsecurity from pg_class where oid='public.material_intake_lots'::regclass),'physical lot RLS is enabled');
select is((select count(*) from pg_policies where schemaname='public' and tablename='material_intake_lots' and cmd in ('INSERT','UPDATE','DELETE')),0::bigint,'physical lot writes are RPC-only');
select is((select count(*) from pg_policies where schemaname='public' and tablename='material_receipts' and cmd in ('INSERT','UPDATE','DELETE')),0::bigint,'reception writes are RPC-only');
select is((select count(*) from public.material_sources s join public.plants p on p.id=s.plant_id where p.code='TAM' and s.code='MUNICIPIO_TAMESIS'),1::bigint,'Támesis stable historical source is seeded');
select is((select count(*) from public.material_sources s join public.plants p on p.id=s.plant_id where p.code='YAR' and s.code='GREENATICS'),1::bigint,'Yarumal stable historical source is seeded');
insert into auth.users(id,email,created_at,updated_at) values ('e1000000-0000-4000-8000-000000000001','reception-operator@greenatics.test',now(),now());
insert into public.plants(id,code,name,active) values ('e2000000-0000-4000-8000-000000000001','R2-TAM','Recepción 2 Támesis',true),('e2000000-0000-4000-8000-000000000002','R2-YAR','Recepción 2 Yarumal',true);
insert into public.profiles(id,display_name) values ('e1000000-0000-4000-8000-000000000001','Reception Operator');
insert into public.plant_memberships(user_id,plant_id,role) values ('e1000000-0000-4000-8000-000000000001','e2000000-0000-4000-8000-000000000001','operator');
insert into public.material_sources(id,plant_id,code,name,source_kind) values ('e3000000-0000-4000-8000-000000000001','e2000000-0000-4000-8000-000000000001','MUNI','Municipio R2','generator'),('e3000000-0000-4000-8000-000000000002','e2000000-0000-4000-8000-000000000002','OTHER','Otra planta','generator');
insert into public.collection_routes(id,plant_id,code,name) values ('e4000000-0000-4000-8000-000000000001','e2000000-0000-4000-8000-000000000001','RUTA1','Ruta 1'),('e4000000-0000-4000-8000-000000000002','e2000000-0000-4000-8000-000000000002','RUTA2','Ruta otra planta');
insert into public.material_types(id,plant_id,code,name) values ('e5000000-0000-4000-8000-000000000001','e2000000-0000-4000-8000-000000000001','FORSU','FORSU R2'),('e5000000-0000-4000-8000-000000000002','e2000000-0000-4000-8000-000000000002','FORSU','FORSU otra planta');
insert into public.employees(id,plant_id,display_name) values ('e6000000-0000-4000-8000-000000000001','e2000000-0000-4000-8000-000000000001','Responsable R2');
set local role authenticated; set local request.jwt.claim.sub='e1000000-0000-4000-8000-000000000001';
select lives_ok($$select public.ops_record_material_receipt_v2('e2000000-0000-4000-8000-000000000001','e3000000-0000-4000-8000-000000000001','e5000000-0000-4000-8000-000000000001','2026-08-10T13:00:00Z','2026-08-10T13:30:00Z',1000,940,60,20,'partial_rejection','e4000000-0000-4000-8000-000000000001','e6000000-0000-4000-8000-000000000001','Carlos Vallejo','3017452101','WLX212','20 kg de impropios separados')$$,'operator records structured reception atomically');
select is((select accepted_weight_kg from public.material_receipts where plant_id='e2000000-0000-4000-8000-000000000001'),940::numeric,'accepted mass is persisted');
select is((select improper_weight_kg from public.material_receipts where plant_id='e2000000-0000-4000-8000-000000000001'),20::numeric,'improper mass is persisted');
select is((select vehicle_plate from public.material_receipts where plant_id='e2000000-0000-4000-8000-000000000001'),'WLX212'::text,'vehicle plate is normalized and persisted');
select is((select count(*) from public.material_intake_lots where plant_id='e2000000-0000-4000-8000-000000000001'),1::bigint,'accepted reception creates one physical lot');
select is((select available_mass_kg from public.material_intake_lots where plant_id='e2000000-0000-4000-8000-000000000001'),940::numeric,'lot starts with accepted mass only');
select is((select status from public.material_intake_lots where plant_id='e2000000-0000-4000-8000-000000000001'),'available'::text,'partial rejection leaves accepted lot available');
select throws_like($$select public.ops_record_material_receipt_v2('e2000000-0000-4000-8000-000000000001','e3000000-0000-4000-8000-000000000002','e5000000-0000-4000-8000-000000000001','2026-08-11T13:00:00Z','2026-08-11T13:30:00Z',100,100,0,0,'accepted')$$,'%origen o generador no pertenece%','cross-plant source is rejected');
select throws_like($$select public.ops_record_material_receipt_v2('e2000000-0000-4000-8000-000000000001','e3000000-0000-4000-8000-000000000001','e5000000-0000-4000-8000-000000000001','2026-08-11T13:00:00Z','2026-08-11T13:30:00Z',100,90,5,0,'partial_rejection')$$,'%debe coincidir%','mass balance mismatch is rejected');
select throws_like($$select public.ops_record_material_receipt_v2('e2000000-0000-4000-8000-000000000001','e3000000-0000-4000-8000-000000000001','e5000000-0000-4000-8000-000000000001','2026-08-11T13:00:00Z','2026-08-11T13:30:00Z',100,90,10,11,'partial_rejection')$$,'%impropios debe estar dentro%','improper mass cannot exceed rejected mass');
select lives_ok($$select public.ops_record_material_receipt_v2('e2000000-0000-4000-8000-000000000001','e3000000-0000-4000-8000-000000000001','e5000000-0000-4000-8000-000000000001','2026-08-12T13:00:00Z','2026-08-12T13:30:00Z',100,0,100,20,'rejected',null,null,'Conductor','3000000000','ABC123','Rechazo total')$$,'fully rejected receipt remains auditable');
select is((select count(*) from public.material_intake_lots l join public.material_receipts r on r.id=l.receipt_id where r.acceptance_status='rejected'),0::bigint,'fully rejected receipt creates no physical lot');
select is((select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='ops_record_material_receipt_v2'),1::bigint,'Reception 2.0 RPC is installed');
select * from finish(); rollback;
